    const counterBase = CH_COUNTER_BASE + ch * 4;
    this.wrPtr(chBase, chBase + 1, trackAddr);
    this.wrPtr(chBase + 2, chBase + 3, trackAddr);
    this.wr(chBase + 4, 0);
    const pm = ch & 3;
