    this.wr(chBase + 7, 0);
    this.wr(chBase + 8, 128);
    this.wr(chBase + 9, 15);
    this.wr(counterBase, 1);
    this.wr(counterBase + 1, 1);
    this.wr(counterBase + 2, 1);
    this.wr(counterBase + 3, 0);
